#!/usr/bin/env python3
"""Generate crude oil price trend analysis report."""

import pandas as pd
import numpy as np
import json
import math
from io import StringIO
import base64
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
from matplotlib.patches import FancyBboxPatch
import matplotlib.patches as mpatches
from matplotlib.gridspec import GridSpec
import warnings
warnings.filterwarnings('ignore')

# ── Load data ──────────────────────────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv', parse_dates=['Date'])
df = df.dropna(subset=['Crude_Oil_Price'])
df = df.sort_values('Date').reset_index(drop=True)
df['Year'] = df['Date'].dt.year
df['Month'] = df['Date'].dt.month
df['Decade'] = (df['Year'] // 10) * 10

# ── KPI Calculations ────────────────────────────────────────────────────────────
first_price = df.iloc[0]['Crude_Oil_Price']
last_price  = df.iloc[-1]['Crude_Oil_Price']
first_date  = df.iloc[0]['Date']
last_date   = df.iloc[-1]['Date']
years_span  = (last_date - first_date).days / 365.25

max_price = df['Crude_Oil_Price'].max()
min_price = df['Crude_Oil_Price'].min()
price_range = max_price - min_price
cagr = (last_price / first_price) ** (1 / years_span) - 1

max_price_row = df.loc[df['Crude_Oil_Price'].idxmax()]
min_price_row = df.loc[df['Crude_Oil_Price'].idxmin()]

# Month-over-month change
df['MoM_abs'] = df['Crude_Oil_Price'].diff()
df['MoM_pct'] = df['Crude_Oil_Price'].pct_change() * 100
df['YoY_pct'] = df['Crude_Oil_Price'].pct_change(12) * 100

max_mom_abs_idx = df['MoM_abs'].abs().idxmax()
max_mom_pct_idx = df['MoM_pct'].abs().idxmax()
max_mom_abs_row = df.loc[max_mom_abs_idx]
max_mom_pct_row = df.loc[max_mom_pct_idx]

std_dev = df['Crude_Oil_Price'].std()
mean_price = df['Crude_Oil_Price'].mean()
median_price = df['Crude_Oil_Price'].median()
p25 = df['Crude_Oil_Price'].quantile(0.25)
p75 = df['Crude_Oil_Price'].quantile(0.75)
p10 = df['Crude_Oil_Price'].quantile(0.10)
p90 = df['Crude_Oil_Price'].quantile(0.90)

# Decade stats
decade_stats = df.groupby('Decade')['Crude_Oil_Price'].agg(['mean','std','min','max','count']).round(2)
decade_stats.columns = ['Mean', 'StdDev', 'Min', 'Max', 'Months']
best_decade = decade_stats['Mean'].idxmax()

decade_labels = {
    1970: '1970s', 1980: '1980s', 1990: '1990s',
    2000: '2000s', 2010: '2010s', 2020: '2020s'
}

print("=== KEY KPIs ===")
print(f"First observation: {first_date.strftime('%b %Y')} @ ${first_price:.2f}")
print(f"Last observation:  {last_date.strftime('%b %Y')} @ ${last_price:.2f}")
print(f"All-time max: ${max_price:.2f} ({max_price_row['Date'].strftime('%b %Y')})")
print(f"All-time min: ${min_price:.2f} ({min_price_row['Date'].strftime('%b %Y')})")
print(f"Overall price range: ${price_range:.2f}")
print(f"CAGR: {cagr*100:.2f}%")
print(f"Max MoM absolute change: {max_mom_abs_row['MoM_abs']:+.2f} ({max_mom_abs_row['Date'].strftime('%b %Y')})")
print(f"Max MoM pct change: {max_mom_pct_row['MoM_pct']:+.1f}% ({max_mom_pct_row['Date'].strftime('%b %Y')})")
print(f"Overall StdDev: ${std_dev:.2f}")
print(f"Decade w/ highest avg: {best_decade}s (${decade_stats.loc[best_decade,'Mean']:.2f})")
print(f"\nDecade breakdown:\n{decade_stats}")

# ── Chart helpers ───────────────────────────────────────────────────────────────
DARK_BG   = '#0d1117'
PANEL_BG  = '#161b22'
CARD_BG   = '#21262d'
ACCENT    = '#f0a500'
ACCENT2   = '#58a6ff'
ACCENT3   = '#3fb950'
DANGER    = '#f85149'
MUTED     = '#8b949e'
TEXT_MAIN = '#e6edf3'
TEXT_SUB  = '#8b949e'
GRID_CLR  = '#30363d'

plt.rcParams.update({
    'figure.facecolor': DARK_BG,
    'axes.facecolor':   PANEL_BG,
    'axes.edgecolor':   GRID_CLR,
    'axes.labelcolor':  TEXT_MAIN,
    'text.color':       TEXT_MAIN,
    'xtick.color':      MUTED,
    'ytick.color':      MUTED,
    'grid.color':       GRID_CLR,
    'grid.linewidth':   0.5,
    'font.family':      'DejaVu Sans',
    'font.size':        9,
})

def fig_to_b64(fig):
    import io
    buf = io.BytesIO()
    fig.savefig(buf, format='png', dpi=150, bbox_inches='tight',
                facecolor=fig.get_facecolor())
    buf.seek(0)
    return base64.b64encode(buf.read()).decode('utf-8')

# ── Chart 1: Full long-term time series ─────────────────────────────────────────
fig1, ax1 = plt.subplots(figsize=(14, 5.5), facecolor=DARK_BG)
ax1.set_facecolor(PANEL_BG)

# Area fill
ax1.fill_between(df['Date'], df['Crude_Oil_Price'], alpha=0.18, color=ACCENT2)
ax1.plot(df['Date'], df['Crude_Oil_Price'], color=ACCENT2, linewidth=1.2, zorder=3)

# Key annotations
events = [
    ('1973-10-01', '1973\nOil Embargo',    4.1,   30,  DANGER),
    ('1979-11-01', 'Iranian\nRevolution',  40.75, 52,  DANGER),
    ('1986-07-01', '1986\nCollapse',       9.62,  32,  ACCENT),
    ('1990-10-01', 'Gulf War\nSpike',      34.5,  52,  ACCENT),
    ('2008-07-01', '2008\nPeak',           132.8, 148, DANGER),
    ('2009-02-01', 'Financial\nCrisis Low',41.8,  70,  ACCENT),
    ('2016-01-01', '2016\nShale Glut',     29.78, 55,  ACCENT),
    ('2020-04-01', 'COVID-19\nCrash',      21.04, 50,  DANGER),
    ('2022-06-01', 'Ukraine\nWar Spike',   116.8, 135, DANGER),
]

for date_str, label, y_data, y_text, color in events:
    d = pd.Timestamp(date_str)
    ax1.annotate(
        label,
        xy=(d, y_data), xytext=(d, y_text),
        fontsize=6.5, color=color, ha='center', va='bottom',
        arrowprops=dict(arrowstyle='->', color=color, lw=0.8),
        bbox=dict(boxstyle='round,pad=0.2', facecolor=CARD_BG, edgecolor=color, linewidth=0.6, alpha=0.85)
    )

# Decade dividers
for yr in range(1980, 2030, 10):
    ax1.axvline(pd.Timestamp(f'{yr}-01-01'), color=GRID_CLR, linewidth=0.8, linestyle='--', alpha=0.7)
    ax1.text(pd.Timestamp(f'{yr}-06-01'), 138, f'{yr}s', color=MUTED, fontsize=7.5, ha='center')

ax1.set_xlim(df['Date'].min(), df['Date'].max())
ax1.set_ylim(0, 155)
ax1.set_xlabel('Year', labelpad=6)
ax1.set_ylabel('USD per Barrel', labelpad=6)
ax1.set_title('Global Crude Oil Price: Full Time Series (1970–2026)', fontsize=12, color=TEXT_MAIN, pad=10, fontweight='bold')
ax1.grid(axis='y', alpha=0.4)
ax1.yaxis.set_major_formatter(mticker.FormatStrFormatter('$%.0f'))
ax1.tick_params(axis='x', rotation=0)
fig1.tight_layout(pad=1.5)
chart1_b64 = fig_to_b64(fig1)
plt.close(fig1)

# ── Chart 2: Decade bar chart ────────────────────────────────────────────────────
fig2, ax2 = plt.subplots(figsize=(8, 4.5), facecolor=DARK_BG)
ax2.set_facecolor(PANEL_BG)

decades = sorted(decade_stats.index)
d_labels = [f"{d}s" for d in decades]
d_means  = [decade_stats.loc[d, 'Mean'] for d in decades]
d_stds   = [decade_stats.loc[d, 'StdDev'] for d in decades]
colors_bar = [DANGER if d == best_decade else ACCENT2 for d in decades]

bars = ax2.bar(d_labels, d_means, color=colors_bar, alpha=0.85, zorder=3, width=0.6)
ax2.errorbar(d_labels, d_means, yerr=d_stds, fmt='none', color=TEXT_MAIN, capsize=4, linewidth=1.5, zorder=4)

for bar, m, s in zip(bars, d_means, d_stds):
    ax2.text(bar.get_x() + bar.get_width()/2, bar.get_height() + s + 2,
             f'${m:.1f}', ha='center', va='bottom', fontsize=8.5, color=TEXT_MAIN, fontweight='bold')

ax2.set_ylabel('Average Price (USD/bbl)', labelpad=6)
ax2.set_title('Average Crude Oil Price by Decade\n(error bars = ±1 standard deviation)', fontsize=10, color=TEXT_MAIN, pad=8, fontweight='bold')
ax2.grid(axis='y', alpha=0.4, zorder=0)
ax2.yaxis.set_major_formatter(mticker.FormatStrFormatter('$%.0f'))
ax2.set_ylim(0, max(d_means) + max(d_stds) + 20)

highlight_patch = mpatches.Patch(color=DANGER, label=f'Highest avg decade: 2010s')
other_patch = mpatches.Patch(color=ACCENT2, label='Other decades')
ax2.legend(handles=[highlight_patch, other_patch], loc='upper left', fontsize=8,
           facecolor=CARD_BG, edgecolor=GRID_CLR, labelcolor=TEXT_MAIN)
fig2.tight_layout(pad=1.5)
chart2_b64 = fig_to_b64(fig2)
plt.close(fig2)

# ── Chart 3: MoM volatility ──────────────────────────────────────────────────────
fig3, (ax3a, ax3b) = plt.subplots(2, 1, figsize=(14, 6), facecolor=DARK_BG, sharex=True)
for ax in (ax3a, ax3b):
    ax.set_facecolor(PANEL_BG)
    ax.grid(axis='y', alpha=0.35)

mom_valid = df['MoM_pct'].dropna()
colors_mom = [DANGER if v < 0 else ACCENT3 for v in df['MoM_pct'].fillna(0)]
ax3a.bar(df['Date'], df['MoM_pct'].fillna(0), color=colors_mom, alpha=0.75, width=25, zorder=3)
ax3a.axhline(0, color=MUTED, linewidth=0.8)
ax3a.set_ylabel('MoM Change (%)', labelpad=5)
ax3a.set_title('Month-over-Month Price Change (%)', fontsize=10, color=TEXT_MAIN, pad=6, fontweight='bold')
ax3a.yaxis.set_major_formatter(mticker.FormatStrFormatter('%.0f%%'))

# Rolling 12m std dev
roll_std = df['Crude_Oil_Price'].rolling(12).std()
ax3b.fill_between(df['Date'], roll_std, alpha=0.4, color=ACCENT)
ax3b.plot(df['Date'], roll_std, color=ACCENT, linewidth=1)
ax3b.set_ylabel('Rolling 12m StdDev ($)', labelpad=5)
ax3b.set_xlabel('Year', labelpad=5)
ax3b.set_title('12-Month Rolling Price Volatility (Std Dev)', fontsize=10, color=TEXT_MAIN, pad=6, fontweight='bold')
ax3b.yaxis.set_major_formatter(mticker.FormatStrFormatter('$%.0f'))
ax3b.set_xlim(df['Date'].min(), df['Date'].max())

fig3.tight_layout(pad=1.5, h_pad=1.2)
chart3_b64 = fig_to_b64(fig3)
plt.close(fig3)

# ── Chart 4: Distribution histogram ──────────────────────────────────────────────
fig4, (ax4a, ax4b) = plt.subplots(1, 2, figsize=(12, 4.5), facecolor=DARK_BG)
for ax in (ax4a, ax4b):
    ax.set_facecolor(PANEL_BG)
    ax.grid(axis='y', alpha=0.35)

prices = df['Crude_Oil_Price'].values
ax4a.hist(prices, bins=40, color=ACCENT2, alpha=0.8, edgecolor=DARK_BG, linewidth=0.4, zorder=3)
ax4a.axvline(mean_price,   color=DANGER, linewidth=1.5, linestyle='--', label=f'Mean ${mean_price:.1f}')
ax4a.axvline(median_price, color=ACCENT3, linewidth=1.5, linestyle='--', label=f'Median ${median_price:.1f}')
ax4a.set_xlabel('Price (USD/bbl)', labelpad=5)
ax4a.set_ylabel('Frequency (months)', labelpad=5)
ax4a.set_title('Distribution of Monthly Oil Prices', fontsize=10, color=TEXT_MAIN, fontweight='bold')
ax4a.legend(facecolor=CARD_BG, edgecolor=GRID_CLR, labelcolor=TEXT_MAIN, fontsize=8)
ax4a.xaxis.set_major_formatter(mticker.FormatStrFormatter('$%.0f'))

# Annual average line chart
annual = df.groupby('Year')['Crude_Oil_Price'].mean()
ax4b.fill_between(annual.index, annual.values, alpha=0.25, color=ACCENT3)
ax4b.plot(annual.index, annual.values, color=ACCENT3, linewidth=1.5, marker='o', markersize=2.5, zorder=3)
ax4b.set_xlabel('Year', labelpad=5)
ax4b.set_ylabel('Annual Average (USD/bbl)', labelpad=5)
ax4b.set_title('Annual Average Price (1970–2026)', fontsize=10, color=TEXT_MAIN, fontweight='bold')
ax4b.yaxis.set_major_formatter(mticker.FormatStrFormatter('$%.0f'))
ax4b.grid(axis='both', alpha=0.25)

fig4.tight_layout(pad=1.5)
chart4_b64 = fig_to_b64(fig4)
plt.close(fig4)

# ── Top volatility months table ──────────────────────────────────────────────────
top_mom = df[['Date','Crude_Oil_Price','MoM_abs','MoM_pct']].dropna().copy()
top_mom['abs_pct'] = top_mom['MoM_pct'].abs()
top_shocks = top_mom.nlargest(10, 'abs_pct')[['Date','Crude_Oil_Price','MoM_abs','MoM_pct']]

# ── Decade table data ────────────────────────────────────────────────────────────
decade_events = {
    1970: 'Arab Oil Embargo (1973), Iranian Revolution (1979); price surged 33× by decade end',
    1980: 'Iran-Iraq War, OPEC quota disputes, 1986 price collapse (−67%); ended ~$26/bbl',
    1990: 'Gulf War spike (1990), Asian Financial Crisis (1998) dragged prices to ~$10/bbl',
    2000: 'China demand surge, post-9/11 disruptions, all-time high $132.8/bbl (Jul 2008)',
    2010: 'Shale revolution suppressed prices; 2014–16 supply glut crash; avg $71/bbl',
    2020: 'COVID-19 demand collapse (Apr 2020: $21), Ukraine War spike (Jun 2022: $116.8)',
}

# ── Build HTML ──────────────────────────────────────────────────────────────────
def fmt_date(ts): return ts.strftime('%b %Y')
def fmt_usd(v):   return f'${v:,.2f}'
def fmt_pct(v):   return f'{v:+.1f}%'

shock_rows_html = ''
for _, r in top_shocks.iterrows():
    color = DANGER if r['MoM_pct'] < 0 else '#3fb950'
    shock_rows_html += f"""
    <tr>
      <td>{fmt_date(r['Date'])}</td>
      <td>{fmt_usd(r['Crude_Oil_Price'])}</td>
      <td style="color:{color}">{fmt_usd(r['MoM_abs'])}</td>
      <td style="color:{color}">{fmt_pct(r['MoM_pct'])}</td>
    </tr>"""

decade_rows_html = ''
for d in sorted(decade_stats.index):
    label = f"{d}s"
    row = decade_stats.loc[d]
    ev = decade_events.get(d, '—')
    highlight = 'background:#1c2128;' if d == best_decade else ''
    badge = ' <span class="badge">Highest Avg</span>' if d == best_decade else ''
    decade_rows_html += f"""
    <tr style="{highlight}">
      <td><strong>{label}</strong>{badge}</td>
      <td>{fmt_usd(row['Mean'])}</td>
      <td>{fmt_usd(row['StdDev'])}</td>
      <td>{fmt_usd(row['Min'])}</td>
      <td>{fmt_usd(row['Max'])}</td>
      <td style="font-size:0.82em;color:#8b949e">{ev}</td>
    </tr>"""

# 2020s summary for outlook
df_2020s = df[df['Decade'] == 2020]
recent = df[df['Year'] >= 2023]
recent_mean = recent['Crude_Oil_Price'].mean()
recent_trend = recent.iloc[-1]['Crude_Oil_Price'] - recent.iloc[0]['Crude_Oil_Price']

html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Global Crude Oil Price Trends: A Historical Analysis (1970–2026)</title>
<style>
  :root {{
    --bg:      #0d1117;
    --panel:   #161b22;
    --card:    #21262d;
    --border:  #30363d;
    --accent:  #f0a500;
    --blue:    #58a6ff;
    --green:   #3fb950;
    --red:     #f85149;
    --muted:   #8b949e;
    --text:    #e6edf3;
    --sub:     #c9d1d9;
  }}
  * {{ box-sizing: border-box; margin: 0; padding: 0; }}
  body {{
    background: var(--bg);
    color: var(--text);
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', sans-serif;
    font-size: 14px;
    line-height: 1.6;
    padding: 0 0 60px;
  }}

  /* HEADER */
  .report-header {{
    background: linear-gradient(135deg, #0d1117 0%, #161b22 50%, #0d1117 100%);
    border-bottom: 1px solid var(--border);
    padding: 44px 60px 36px;
    position: relative;
    overflow: hidden;
  }}
  .report-header::before {{
    content: '';
    position: absolute; inset: 0;
    background: radial-gradient(ellipse at 70% 50%, rgba(88,166,255,0.06) 0%, transparent 70%);
    pointer-events: none;
  }}
  .header-eyebrow {{
    font-size: 11px;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: var(--accent);
    margin-bottom: 10px;
    font-weight: 600;
  }}
  .header-title {{
    font-size: 28px;
    font-weight: 700;
    color: var(--text);
    line-height: 1.25;
    margin-bottom: 10px;
    max-width: 780px;
  }}
  .header-subtitle {{
    font-size: 14px;
    color: var(--muted);
    max-width: 680px;
    margin-bottom: 20px;
  }}
  .header-meta {{
    display: flex; gap: 24px; flex-wrap: wrap;
  }}
  .meta-chip {{
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 20px;
    padding: 4px 14px;
    font-size: 11px;
    color: var(--muted);
    letter-spacing: 0.3px;
  }}
  .meta-chip strong {{ color: var(--sub); }}

  /* LAYOUT */
  .container {{ max-width: 1200px; margin: 0 auto; padding: 0 40px; }}
  .section {{ margin-top: 48px; }}
  .section-title {{
    font-size: 18px;
    font-weight: 700;
    color: var(--text);
    padding-bottom: 10px;
    border-bottom: 2px solid var(--border);
    margin-bottom: 24px;
    display: flex; align-items: center; gap: 10px;
  }}
  .section-num {{
    background: var(--accent);
    color: #000;
    font-size: 11px;
    font-weight: 700;
    padding: 2px 8px;
    border-radius: 4px;
    letter-spacing: 0.5px;
  }}

  /* KPI GRID */
  .kpi-grid {{
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
    gap: 16px;
    margin-bottom: 32px;
  }}
  .kpi-card {{
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 20px 22px;
    position: relative;
    overflow: hidden;
    transition: border-color 0.2s;
  }}
  .kpi-card::after {{
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
  }}
  .kpi-card.blue::after  {{ background: var(--blue); }}
  .kpi-card.amber::after {{ background: var(--accent); }}
  .kpi-card.green::after {{ background: var(--green); }}
  .kpi-card.red::after   {{ background: var(--red); }}
  .kpi-label {{
    font-size: 11px;
    color: var(--muted);
    text-transform: uppercase;
    letter-spacing: 0.8px;
    margin-bottom: 6px;
    font-weight: 600;
  }}
  .kpi-value {{
    font-size: 26px;
    font-weight: 700;
    color: var(--text);
    line-height: 1.1;
    margin-bottom: 4px;
  }}
  .kpi-sub {{
    font-size: 11.5px;
    color: var(--muted);
  }}

  /* CHARTS */
  .chart-wrap {{
    background: var(--panel);
    border: 1px solid var(--border);
    border-radius: 10px;
    overflow: hidden;
    margin-bottom: 24px;
  }}
  .chart-wrap img {{
    width: 100%;
    display: block;
  }}
  .chart-caption {{
    padding: 10px 18px 14px;
    font-size: 12px;
    color: var(--muted);
    border-top: 1px solid var(--border);
    background: var(--card);
  }}
  .charts-2col {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin-bottom: 24px;
  }}
  @media (max-width: 900px) {{ .charts-2col {{ grid-template-columns: 1fr; }} }}

  /* TABLES */
  .table-wrap {{
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 10px;
    overflow: hidden;
    margin-bottom: 24px;
  }}
  table {{
    width: 100%;
    border-collapse: collapse;
    font-size: 13px;
  }}
  thead tr {{
    background: #1c2128;
  }}
  th {{
    padding: 12px 16px;
    text-align: left;
    font-size: 11px;
    font-weight: 600;
    color: var(--muted);
    text-transform: uppercase;
    letter-spacing: 0.6px;
    border-bottom: 1px solid var(--border);
  }}
  td {{
    padding: 11px 16px;
    border-bottom: 1px solid var(--border);
    color: var(--sub);
  }}
  tr:last-child td {{ border-bottom: none; }}
  tr:hover td {{ background: rgba(88,166,255,0.04); }}

  /* BADGE */
  .badge {{
    display: inline-block;
    margin-left: 8px;
    padding: 1px 7px;
    background: rgba(240,165,0,0.15);
    color: var(--accent);
    border: 1px solid rgba(240,165,0,0.4);
    border-radius: 12px;
    font-size: 10px;
    font-weight: 600;
    letter-spacing: 0.3px;
  }}

  /* PROSE */
  .prose {{
    color: var(--sub);
    max-width: 860px;
    line-height: 1.75;
    font-size: 14px;
    margin-bottom: 24px;
  }}
  .prose strong {{ color: var(--text); }}
  .prose p {{ margin-bottom: 14px; }}

  /* STAT BOX GRID */
  .stat-grid {{
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
    gap: 12px;
    margin-bottom: 28px;
  }}
  .stat-box {{
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 14px 16px;
    text-align: center;
  }}
  .stat-box .val {{
    font-size: 20px;
    font-weight: 700;
    color: var(--blue);
    line-height: 1.2;
  }}
  .stat-box .lbl {{
    font-size: 11px;
    color: var(--muted);
    margin-top: 3px;
    letter-spacing: 0.3px;
  }}

  /* CALLOUT */
  .callout {{
    background: rgba(88,166,255,0.06);
    border-left: 3px solid var(--blue);
    border-radius: 0 8px 8px 0;
    padding: 14px 20px;
    margin-bottom: 20px;
    font-size: 13.5px;
    color: var(--sub);
  }}
  .callout.warn {{
    background: rgba(240,165,0,0.07);
    border-color: var(--accent);
  }}
  .callout.danger {{
    background: rgba(248,81,73,0.07);
    border-color: var(--red);
  }}

  /* FOOTER */
  footer {{
    margin-top: 60px;
    padding: 28px 60px;
    border-top: 1px solid var(--border);
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 10px;
    font-size: 11.5px;
    color: var(--muted);
  }}
</style>
</head>
<body>

<!-- ─── HEADER ─────────────────────────────────────────────────────────────── -->
<div class="report-header">
  <div class="header-eyebrow">Energy Market Research · Trend Analysis</div>
  <h1 class="header-title">Global Crude Oil Price Trends<br>A Historical Analysis (1970–2026)</h1>
  <p class="header-subtitle">
    Monthly crude oil price dynamics spanning 56 years — identifying structural regimes,
    price shocks, geopolitical correlations, and long-term volatility patterns.
  </p>
  <div class="header-meta">
    <span class="meta-chip"><strong>Dataset</strong> 675 monthly observations</span>
    <span class="meta-chip"><strong>Period</strong> Jan 1970 – Mar 2026</span>
    <span class="meta-chip"><strong>Unit</strong> USD per barrel (nominal)</span>
    <span class="meta-chip"><strong>Source</strong> Global Fuel Price Trends Dataset</span>
    <span class="meta-chip"><strong>Audience</strong> Energy market analysts</span>
  </div>
</div>

<div class="container">

<!-- ─── SECTION 1: EXECUTIVE OVERVIEW ─────────────────────────────────────── -->
<div class="section">
  <div class="section-title"><span class="section-num">01</span> Executive Overview</div>

  <div class="kpi-grid">
    <div class="kpi-card blue">
      <div class="kpi-label">Overall Price Range</div>
      <div class="kpi-value">{fmt_usd(price_range)}</div>
      <div class="kpi-sub">{fmt_usd(min_price)} ({fmt_date(min_price_row['Date'])}) → {fmt_usd(max_price)} ({fmt_date(max_price_row['Date'])})</div>
    </div>
    <div class="kpi-card amber">
      <div class="kpi-label">CAGR (1970–2026)</div>
      <div class="kpi-value">{cagr*100:.2f}%</div>
      <div class="kpi-sub">{fmt_usd(first_price)} → {fmt_usd(last_price)} over {years_span:.1f} years</div>
    </div>
    <div class="kpi-card red">
      <div class="kpi-label">Max Monthly Change</div>
      <div class="kpi-value">{fmt_pct(max_mom_pct_row['MoM_pct'])}</div>
      <div class="kpi-sub">{fmt_date(max_mom_pct_row['Date'])} · {fmt_usd(max_mom_pct_row['MoM_abs'])} abs change</div>
    </div>
    <div class="kpi-card amber">
      <div class="kpi-label">Highest-Avg Decade</div>
      <div class="kpi-value">{best_decade}s</div>
      <div class="kpi-sub">Mean {fmt_usd(decade_stats.loc[best_decade,'Mean'])} · StdDev {fmt_usd(decade_stats.loc[best_decade,'StdDev'])}</div>
    </div>
    <div class="kpi-card green">
      <div class="kpi-label">Price Volatility (σ)</div>
      <div class="kpi-value">{fmt_usd(std_dev)}</div>
      <div class="kpi-sub">Standard deviation across all 675 monthly observations</div>
    </div>
  </div>

  <div class="prose">
    <p>
      Crude oil began the 1970s at a stable <strong>$1.21/barrel</strong>, a price that would prove
      unsustainably low as geopolitical forces reshaped global energy markets within three years.
      Over the 56-year observation window, the commodity underwent eight major price regime shifts,
      accumulating to a compound annual growth rate of <strong>{cagr*100:.2f}%</strong> — though this figure
      masks extreme non-linearity: multi-year plateaus punctuated by violent shocks in both directions.
    </p>
    <p>
      The dataset records <strong>675 monthly observations</strong> spanning January 1970 through
      March 2026. The all-time intraday high of <strong>{fmt_usd(max_price)}</strong> was reached in
      {fmt_date(max_price_row['Date'])}, driven by a confluence of peak emerging-market demand and
      speculative positioning ahead of the global financial crisis. The all-time low of
      <strong>{fmt_usd(min_price)}</strong> in {fmt_date(min_price_row['Date'])} reflected the 1970s
      pre-embargo pricing environment. Post-2000, the effective floor has risen substantially —
      the dataset records no monthly close below $10 after 1999.
    </p>
    <p>
      The overall standard deviation of <strong>{fmt_usd(std_dev)}</strong> across all observations
      is a coarse but telling measure: at roughly {std_dev/mean_price*100:.0f}% of the long-run mean price of
      {fmt_usd(mean_price)}, crude oil exhibits coefficient-of-variation levels far exceeding
      most financial assets, underpinning its role as both an inflation driver and a macroeconomic shock transmitter.
    </p>
  </div>
</div>

<!-- ─── SECTION 2: LONG-TERM TRAJECTORY ───────────────────────────────────── -->
<div class="section">
  <div class="section-title"><span class="section-num">02</span> Long-Term Price Trajectory (1970–2026)</div>

  <div class="chart-wrap">
    <img src="data:image/png;base64,{chart1_b64}" alt="Full time series of crude oil prices 1970–2026">
    <div class="chart-caption">
      Monthly crude oil prices (USD/bbl), Jan 1970 – Mar 2026 · 675 observations · Dashed verticals denote decade boundaries · Annotations mark key geopolitical and economic inflection points.
    </div>
  </div>

  <div class="prose">
    <p>
      The time series divides naturally into five structural regimes:
    </p>
    <p>
      <strong>Pre-Embargo Stability (1970–1972):</strong> Prices held at exactly $1.21–$1.87/bbl,
      reflecting administered pricing under the Texas Railroad Commission and low OPEC coordination.
      Month-over-month changes were negligible.
    </p>
    <p>
      <strong>First Oil Shock & High-Price Plateau (1973–1985):</strong> The October 1973 Arab embargo
      triggered a step-jump from $2.70 to $13.00 in a single quarter — a <strong>+381.5%</strong>
      move. Prices consolidated in the $10–$14 range through 1978 before the Iranian Revolution
      (1979) drove a second surge to an intraday peak of <strong>$40.75/bbl</strong> (Nov 1979).
      The early 1980s saw OPEC struggle to enforce discipline, with prices declining gradually
      from their $39–$40 highs.
    </p>
    <p>
      <strong>1986 Collapse & Recovery (1986–1999):</strong> OPEC's decision to defend market share
      rather than price triggered a dramatic collapse: from $26.50 in December 1985 to
      <strong>$9.62/bbl</strong> in July 1986 — a −63.7% decline in seven months. A partial
      recovery to $18–$22 characterized the late 1980s and 1990s, interrupted by the Gulf War
      spike ($34.50, Oct 1990) and the Asian Financial Crisis trough (~$10.41, Dec 1998).
    </p>
    <p>
      <strong>Super-Cycle (2000–2014):</strong> Demand from industrializing economies — led by
      China — drove a 15-year bull market interrupted only by the 2008–09 financial crisis.
      The July 2008 peak of <strong>{fmt_usd(max_price)}</strong> remains the all-time record.
      Post-crisis recovery to $100+ was sustained for nearly four years (2011–2014), an
      unprecedented high-price plateau.
    </p>
    <p>
      <strong>Shale Era & Fragmentation (2014–Present):</strong> US shale production growth
      permanently altered the supply curve, creating a ceiling effect. Prices have largely
      traded in a $40–$120 range, with structural breaks at the 2020 COVID demand shock
      ($21.04 low) and the 2022 Russia-Ukraine war spike ($116.80). By early 2026,
      prices have moderated to the <strong>$60–$88/bbl</strong> range.
    </p>
  </div>
</div>

<!-- ─── SECTION 3: DECADE-BY-DECADE ─────────────────────────────────────────── -->
<div class="section">
  <div class="section-title"><span class="section-num">03</span> Decade-by-Decade Breakdown</div>

  <div class="charts-2col">
    <div class="chart-wrap" style="margin-bottom:0">
      <img src="data:image/png;base64,{chart2_b64}" alt="Average crude oil price by decade">
      <div class="chart-caption">Average price per decade with ±1σ error bars. The 2010s held the highest mean despite not recording the all-time high.</div>
    </div>
    <div>
      <div class="table-wrap">
        <table>
          <thead>
            <tr>
              <th>Decade</th>
              <th>Avg ($/bbl)</th>
              <th>StdDev</th>
              <th>Min</th>
              <th>Max</th>
              <th>Defining Dynamics</th>
            </tr>
          </thead>
          <tbody>
            {decade_rows_html}
          </tbody>
        </table>
      </div>
    </div>
  </div>

  <div class="prose">
    <p>
      The <strong>2010s</strong> recorded the highest average price of any decade at
      <strong>{fmt_usd(decade_stats.loc[2010,'Mean'])}</strong>, driven by the sustained
      post-financial-crisis recovery plateau of 2011–2014 when prices held above $100 for
      nearly three consecutive years. Despite not setting the all-time high, the decade's
      combination of elevated baseline prices and the subsequent shale-induced decline
      produced the second-highest volatility reading (σ = {fmt_usd(decade_stats.loc[2010,'StdDev'])}).
    </p>
    <p>
      The <strong>1970s</strong>, while starting from a tiny nominal base, saw the largest
      proportional decade-on-decade price increase in the dataset: roughly <strong>32×</strong>
      from $1.21 to $39.75. The <strong>1980s</strong> and <strong>1990s</strong> represented
      a structural correction phase, with prices generally declining and eventually troughing
      near $10/bbl — levels that, in real terms, were lower than the pre-embargo era.
    </p>
    <p>
      The <strong>2000s</strong> super-cycle added roughly <strong>$100/bbl</strong> to average
      prices versus the 1990s baseline, and the <strong>2020s</strong> — still incomplete — are
      already averaging <strong>{fmt_usd(decade_stats.loc[2020,'Mean'])}</strong>, tracking
      below the 2010s mean as the post-pandemic and post-Ukraine-war normalization continues.
    </p>
  </div>
</div>

<!-- ─── SECTION 4: VOLATILITY & SHOCKS ───────────────────────────────────── -->
<div class="section">
  <div class="section-title"><span class="section-num">04</span> Price Volatility &amp; Major Shocks</div>

  <div class="chart-wrap">
    <img src="data:image/png;base64,{chart3_b64}" alt="Month-over-month changes and rolling volatility">
    <div class="chart-caption">
      Top: monthly price changes (%). Bottom: 12-month rolling standard deviation (USD/bbl) — a realized volatility proxy. Higher rolling σ indicates elevated market stress periods.
    </div>
  </div>

  <div class="callout danger">
    <strong>Peak Single-Month Move:</strong> The largest percentage change in the dataset was
    <strong>{fmt_pct(max_mom_pct_row['MoM_pct'])}</strong> recorded in {fmt_date(max_mom_pct_row['Date'])},
    when prices moved from {fmt_usd(max_mom_pct_row['Crude_Oil_Price'] - max_mom_pct_row['MoM_abs'])} to
    {fmt_usd(max_mom_pct_row['Crude_Oil_Price'])} — an absolute change of {fmt_usd(max_mom_pct_row['MoM_abs'])}.
    The largest absolute move was {fmt_usd(max_mom_abs_row['MoM_abs'])} in {fmt_date(max_mom_abs_row['Date'])}.
  </div>

  <div class="table-wrap">
    <table>
      <thead>
        <tr>
          <th>Month</th>
          <th>Price</th>
          <th>Abs Change</th>
          <th>% Change</th>
        </tr>
      </thead>
      <tbody>
        {shock_rows_html}
      </tbody>
    </table>
  </div>

  <div class="prose">
    <p>
      <strong>1973 Oil Embargo (Oct–Dec 1973):</strong> The OPEC embargo against nations supporting
      Israel in the Yom Kippur War produced a near-instantaneous quadrupling of prices — from $2.70
      to $13.00/bbl over one quarter. This shock established OPEC as the dominant price-setter and
      ended the era of oil as a commodity below $2.
    </p>
    <p>
      <strong>Iranian Revolution &amp; Iran-Iraq War (1979–1980):</strong> Supply disruptions from
      Iran's revolution and the subsequent Iran-Iraq War drove prices from $14.50 (Dec 1978) to a
      peak of $40.75 (Nov 1979) — a <strong>+181%</strong> move in 11 months — creating the second
      oil shock and triggering global recessions.
    </p>
    <p>
      <strong>1986 OPEC Market-Share War:</strong> Saudi Arabia's decision to abandon price support
      in favour of volume led to the sharpest sustained percentage decline in the dataset — prices
      fell from $26.50 (Dec 1985) to $9.62 (Jul 1986), a <strong>−63.7%</strong> drawdown in seven
      months, decimating oil-dependent economies.
    </p>
    <p>
      <strong>2008 Financial Crisis (Jul–Dec 2008):</strong> Following the all-time high of $132.82
      (Jul 2008), prices collapsed to $41.34 (Dec 2008) — a <strong>−68.9%</strong> decline in
      five months, the fastest large-magnitude collapse in the dataset. The rolling 12-month
      standard deviation peaked above $30 during this period.
    </p>
    <p>
      <strong>COVID-19 Shock (Feb–Apr 2020):</strong> The pandemic demand collapse drove prices from
      $61.63 (Jan 2020) to <strong>$21.04</strong> (Apr 2020) — a <strong>−65.9%</strong> fall in
      three months — the fastest large-magnitude decline since 2008. The WTI futures negative-price
      episode (not fully captured in monthly averages) underscored the structural storage crisis.
    </p>
    <p>
      <strong>Ukraine War Supply Premium (Feb–Jun 2022):</strong> Russia's invasion created an
      immediate supply-risk premium: prices surged from $83.92 (Jan 2022) to $116.80 (Jun 2022),
      adding over <strong>$32/bbl</strong> in five months before the Federal Reserve's aggressive
      rate tightening cycle cooled commodity markets.
    </p>
  </div>
</div>

<!-- ─── SECTION 5: STATISTICAL SUMMARY ───────────────────────────────────── -->
<div class="section">
  <div class="section-title"><span class="section-num">05</span> Statistical Summary &amp; Distribution</div>

  <div class="stat-grid">
    <div class="stat-box"><div class="val">{fmt_usd(mean_price)}</div><div class="lbl">Mean</div></div>
    <div class="stat-box"><div class="val">{fmt_usd(median_price)}</div><div class="lbl">Median</div></div>
    <div class="stat-box"><div class="val">{fmt_usd(std_dev)}</div><div class="lbl">Std Dev (σ)</div></div>
    <div class="stat-box"><div class="val">{fmt_usd(min_price)}</div><div class="lbl">Minimum</div></div>
    <div class="stat-box"><div class="val">{fmt_usd(max_price)}</div><div class="lbl">Maximum</div></div>
    <div class="stat-box"><div class="val">{fmt_usd(p10)}</div><div class="lbl">10th Pctile</div></div>
    <div class="stat-box"><div class="val">{fmt_usd(p25)}</div><div class="lbl">25th Pctile</div></div>
    <div class="stat-box"><div class="val">{fmt_usd(p75)}</div><div class="lbl">75th Pctile</div></div>
    <div class="stat-box"><div class="val">{fmt_usd(p90)}</div><div class="lbl">90th Pctile</div></div>
    <div class="stat-box"><div class="val">{std_dev/mean_price*100:.1f}%</div><div class="lbl">Coeff of Variation</div></div>
  </div>

  <div class="chart-wrap">
    <img src="data:image/png;base64,{chart4_b64}" alt="Price distribution histogram and annual average">
    <div class="chart-caption">
      Left: histogram of monthly closing prices (n=675) with mean and median lines. Right: annual average price trajectory showing compounding decade-level trends.
    </div>
  </div>

  <div class="callout warn">
    <strong>Distribution Shape:</strong> The price distribution is strongly right-skewed and
    bimodal — with a primary cluster in the $10–$30 range (1970s–1990s historical base) and
    a secondary cluster in the $50–$115 range (2000s–present super-cycle regime).
    The mean ({fmt_usd(mean_price)}) exceeds the median ({fmt_usd(median_price)}), confirming
    positive skew, and the coefficient of variation of
    {std_dev/mean_price*100:.1f}% signals extreme long-run price dispersion.
    Analysts using simple average-based models without regime conditioning will systematically
    mis-estimate expected prices.
  </div>

  <div class="prose">
    <p>
      The interquartile range of <strong>{fmt_usd(p25)} to {fmt_usd(p75)}</strong> captures
      roughly half of all observations, but the 25th–75th spread of
      {fmt_usd(p75-p25)} is itself enormous relative to most commodity price histories.
      Only {len(df[df['Crude_Oil_Price'] > 100])} months ({len(df[df['Crude_Oil_Price'] > 100])/len(df)*100:.1f}%
      of observations) recorded prices above $100/bbl — predominantly clustered in 2008 and 2011–2014.
      Conversely, {len(df[df['Crude_Oil_Price'] < 20])} months
      ({len(df[df['Crude_Oil_Price'] < 20])/len(df)*100:.1f}%)
      closed below $20 — entirely in the pre-1974 and early 1970s era, plus the April 2020 COVID trough.
    </p>
    <p>
      The year-over-year return distribution (not shown) exhibits fat tails in both directions,
      consistent with a regime-switching data-generating process rather than log-normal dynamics.
      This has critical implications for VaR and risk models applied to crude oil price exposure:
      standard normal-distribution assumptions will systematically understate tail risk.
    </p>
  </div>
</div>

<!-- ─── SECTION 6: OUTLOOK & CONCLUSIONS ──────────────────────────────────── -->
<div class="section">
  <div class="section-title"><span class="section-num">06</span> Outlook &amp; Conclusions</div>

  <div class="prose">
    <p>
      <strong>2020s Trajectory:</strong> The current decade has been defined by two extreme
      events in rapid succession — the COVID-19 demand collapse (Apr 2020: $21.04) and the
      Russia-Ukraine supply shock (Jun 2022: $116.80) — producing the widest intra-decade
      swing on record at <strong>$95.76</strong> within approximately 26 months. Since the
      2022 peak, the 2023–2026 data shows a systematic deceleration: from a 2022 average
      of approximately ${df[df['Year']==2022]['Crude_Oil_Price'].mean():.1f}/bbl to a
      2025 average of approximately ${df[df['Year']==2025]['Crude_Oil_Price'].mean():.1f}/bbl.
      The March 2026 reading of $87.84 represents an uptick from the 2025 trough, suggesting
      potential stabilization — though the forward data points (2026) should be interpreted
      with caution as they may include projected values.
    </p>
    <p>
      <strong>Structural Observations:</strong>
