#!/usr/bin/env python3
"""Generate crude oil price trend analysis report."""

import pandas as pd
import numpy as np
import json
import math
from io import StringIO
import base64
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
from matplotlib.patches import FancyBboxPatch
import matplotlib.patches as mpatches
from matplotlib.gridspec import GridSpec
import warnings
warnings.filterwarnings('ignore')

# ── Load data ──────────────────────────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv', parse_dates=['Date'])
df = df.dropna(subset=['Crude_Oil_Price'])
df = df.sort_values('Date').reset_index(drop=True)
df['Year'] = df['Date'].dt.year
df['Month'] = df['Date'].dt.month
df['Decade'] = (df['Year'] // 10) * 10

# ── KPI Calculations ────────────────────────────────────────────────────────────
first_price = df.iloc[0]['Crude_Oil_Price']
last_price  = df.iloc[-1]['Crude_Oil_Price']
first_date  = df.iloc[0]['Date']
last_date   = df.iloc[-1]['Date']
years_span  = (last_date - first_date).days / 365.25

max_price = df['Crude_Oil_Price'].max()
min_price = df['Crude_Oil_Price'].min()
price_range = max_price - min_price
cagr = (last_price / first_price) ** (1 / years_span) - 1

max_price_row = df.loc[df['Crude_Oil_Price'].idxmax()]
min_price_row = df.loc[df['Crude_Oil_Price'].idxmin()]

# Month-over-month change
df['MoM_abs'] = df['Crude_Oil_Price'].diff()
df['MoM_pct'] = df['Crude_Oil_Price'].pct_change() * 100
df['YoY_pct'] = df['Crude_Oil_Price'].pct_change(12) * 100

max_mom_abs_idx = df['MoM_abs'].abs().idxmax()
max_mom_pct_idx = df['MoM_pct'].abs().idxmax()
max_mom_abs_row = df.loc[max_mom_abs_idx]
max_mom_pct_row = df.loc[max_mom_pct_idx]

std_dev = df['Crude_Oil_Price'].std()
mean_price = df['Crude_Oil_Price'].mean()
median_price = df['Crude_Oil_Price'].median()
p25 = df['Crude_Oil_Price'].quantile(0.25)
p75 = df['Crude_Oil_Price'].quantile(0.75)
p10 = df['Crude_Oil_Price'].quantile(0.10)
p90 = df['Crude_Oil_Price'].quantile(0.90)

# Decade stats
decade_stats = df.groupby('Decade')['Crude_Oil_Price'].agg(['mean','std','min','max','count']).round(2)
decade_stats.columns = ['Mean', 'StdDev', 'Min', 'Max', 'Months']
best_decade = decade_stats['Mean'].idxmax()

decade_labels = {
    1970: '1970s', 1980: '1980s', 1990: '1990s',
    2000: '2000s', 2010: '2010s', 2020: '2020s'
}

print("=== KEY KPIs ===")
print(f"First observation: {first_date.strftime('%b %Y')} @ ${first_price:.2f}")
print(f"Last observation:  {last_date.strftime('%b %Y')} @ ${last_price:.2f}")
print(f"All-time max: ${max_price:.2f} ({max_price_row['Date'].strftime('%b %Y')})")
print(f"All-time min: ${min_price:.2f} ({min_price_row['Date'].strftime('%b %Y')})")
print(f"Overall price range: ${price_range:.2f}")
print(f"CAGR: {cagr*100:.2f}%")
print(f"Max MoM absolute change: {max_mom_abs_row['MoM_abs']:+.2f} ({max_mom_abs_row['Date'].strftime('%b %Y')})")
print(f"Max MoM pct change: {max_mom_pct_row['MoM_pct']:+.1f}% ({max_mom_pct_row['Date'].strftime('%b %Y')})")
print(f"Overall StdDev: ${std_dev:.2f}")
print(f"Decade w/ highest avg: {best_decade}s (${decade_stats.loc[best_decade,'Mean']:.2f})")
print(f"\nDecade breakdown:\n{decade_stats}")

# ── Chart helpers ───────────────────────────────────────────────────────────────
DARK_BG   = '#0d1117'
